import type { BlogArticleFaq } from '../../../types/blog';

export const BODY: string = "\n<p>你的 iPhone 拍出的照片很美，却存成了一种半个世界都打不开的格式。把这些 HEIC 文件转成 JPG 不到一分钟，结果哪里都能用。</p>\n<p>不用安装应用，不用注册账号，不用上传到服务器。转换在你的浏览器里、在你自己的设备上运行。</p>\n<p>这篇指南按步骤走，从挑选照片到下载做好的 JPG，每一步都讲到。</p>\n<h2 id=\"before-you-start\">开始之前：需要准备什么</h2>\n<p>你只需要 HEIC 文件和一个现代浏览器。Chrome、Safari、Edge、Firefox 都行，电脑、手机、平板上都能用。</p>\n<p>照片在相机胶卷或文件里找。iPhone 上是相机保存的照片，电脑上是别人发来的 .heic 文件。</p>\n<p>先弄清 JPG 是干什么用的。表格可能要求文件大小上限，打印店可能要求最高画质，用途决定设置。</p>\n<p>每张文件最大接受 25MB。所有标准 iPhone 照片都在这个范围内，包括 4800 万像素的 ProRAW 照片，不用任何准备。</p>\n<h2 id=\"step-1-open-tool\">第 1 步：打开 HEIC 转 JPG 工具</h2>\n<p>在浏览器里打开<a href=\"/zh/heic-zhuan-jpg/\">HEIC 转 JPG 工具</a>。页面很简单：一个上传区域、一个画质滑块、一个下载按钮。</p>\n<p>Windows、Mac、Linux、ChromeOS、安卓、iOS 上都能用。不用安装，不用注册账号。</p>\n<p>用 iPhone 的话，在 Safari 里打开这个页面。它已经在手机上了，转换直接在手机上运行。</p>\n<p>第一次使用时，工具会加载一个小型解码器。这只要一秒钟，之后转换就很快了。</p>\n<h2 id=\"step-2-upload\">第 2 步：上传 HEIC 照片</h2>\n<p>把 HEIC 文件拖到上传区域，或者点一下打开文件选择器。一次可以选好几张照片。</p>\n<p>iPhone 上点上传区域，从图库里选照片。安卓上从相册或文件管理器里选。</p>\n<p>每张照片都会显示成一张带缩略图的卡片，确认传的是正确的图片。传错了很容易发现、删掉。</p>\n<p>电脑上也可以用 Ctrl+V 粘贴复制的图片。有人在聊天里发来 HEIC 文件、想马上转换时，这个办法很方便。</p>\n<h2 id=\"step-3-quality\">第 3 步：检查画质设置</h2>\n<p>画质滑块默认 90%，大多数照片用这个设置就对了。它保留精细细节，文件大小也合理。</p>\n<p>没有理由改就留在 90%。通常的理由是表格有严格的大小限制，即便如此，也要逐步调整。</p>\n<p>JPG 出来太大时，把滑块降到 80%。这一步常常能让文件小一半，肉眼几乎看不出变化。</p>\n<p>只有打算打印的照片才调到 95%。打印会暴露屏幕看不出的瑕疵，单张重要照片多出来的体积不算什么。</p>\n<h2 id=\"step-4-convert\">第 4 步：转换照片</h2>\n<p>点“转换”按钮。解码器读取每张 HEIC 文件，渲染照片，导出 JPG。</p>\n<p>标准的 1200 万像素照片只要一两秒。4800 万像素的照片稍久一点，因为要解码的数据多得多。</p>\n<p>每张卡片完成后都会更新，显示新 JPG 的大小和原来 HEIC 的大小。JPG 通常更大，这是正常的。</p>\n<p>某个文件失败时，读一下错误提示。损坏的文件或名字不对的文件是最常见的原因，其余批量继续转换。</p>\n<h2 id=\"step-5-preview\">第 5 步：下载前预览</h2>\n<p>点任意卡片上的“对比”，并排查看原图和转好的 JPG。拖动分割线，仔细检查照片。</p>\n<p>先检查脸部，因为人最先注意的就是脸。再检查头发、布料、背景文字这类精细细节。</p>\n<p>颜色也要看。Display P3 广色域的颜色在转换中会轻微偏移，预览能看出这个偏移对这张照片有没有影响。</p>\n<p>照片发软时，把画质调高再转一次。原 HEIC 还留在队列里，不用重新上传。</p>\n<h2 id=\"step-6-download\">第 6 步：下载 JPG</h2>\n<p>点单张卡片上的“下载”，保存一张 JPG。文件名保留原名、换成 .jpg 后缀，很好找。</p>\n<p>照片很多时，点“全部下载”，拿到一个装着所有转好 JPG 的 ZIP 包。比一张一张下载快得多。</p>\n<p>使用之前检查一次下载好的文件。在看图软件里打开一张 JPG，确认样子没问题，确认它能在需要的应用里打开。</p>\n<p>HEIC 原文件留着。它们是你手里画质最好的副本，以后需要别的格式还能再转。</p>\n<ol>\n<li>打开 HEIC 转 JPG 工具，上传照片。</li>\n<li>检查画质滑块，默认是 90%。</li>\n<li>转换后用“对比”预览，检查脸部和颜色。</li>\n<li>下载单张 JPG，或者整批打成 ZIP 下载。</li>\n</ol>\n<h2 id=\"converting-on-iphone\">直接在 iPhone 上转换</h2>\n<p>在 iPhone 的 Safari 里打开工具。点上传区域，相册会打开让你选图片。</p>\n<p>选好需要的照片。它们从图库进入转换器，转换在手机本身运行。</p>\n<p>下载的文件在“文件”应用里。打开“文件”，点“下载”，JPG 就在那里，可以分享或附到表格上。</p>\n<p>这是把 iPhone 照片发给 Windows 用户最快的方法。在手机上转好，再从“文件”里分享 JPG，对方马上就能打开。</p>\n<h2 id=\"converting-a-whole-album\">整本相册一次转换</h2>\n<p>整本相册拖进转换器，不用一张一张转。每张 HEIC 用同样的设置转换，ZIP 里装着全部结果。</p>\n<p>相册转换时留意错误标记。一张损坏的文件只会显示警告，不会打断其余文件，好的照片照样完成。</p>\n<p>用批量汇总看总体积。两百张照片的旅行相册可能产出一个很大的 ZIP，下载前先看总数。</p>\n<p>相册里照片和截图混在一起时，先分类。截图用 90% 转也很好，但之后可能需要不同的处理。</p>\n<h2 id=\"after-converting\">转换之后：接下来做什么</h2>\n<p>JPG 要交给表格时，上传前先看大小限制。90% 画质的转好 JPG 可能超过 2MB 的上限，需要压缩。</p>\n<p>网站要求精确大小时，用<a href=\"/zh/tupian-yasuo-dao-100kb/\">100KB 压缩工具</a>或<a href=\"/zh/mubiao-wenjian-daxiao-yasuo/\">目标文件大小压缩工具</a>。先转换、再压缩，按这个顺序。</p>\n<p>JPG 要放到网站上时，考虑再转成 WebP。<a href=\"/zh/jpg-zhuan-webp/\">JPG 转 WebP 工具</a>能把新 JPG 进一步缩小，适合上网。</p>\n<p>JPG 要打印时，画质保持在 90% 或更高。打印会暴露压缩瑕疵，高画质 JPG 是最安全的选择。</p>\n<h2 id=\"fixing-problems\">常见问题怎么解决</h2>\n<p>文件报“无效的 HEIC”错误，先确认它是不是真正的 HEIC 照片。先在 iPhone 上打开它，那里也打不开的话，文件就是损坏的。</p>\n<p>转换很慢，照片很可能是 4800 万像素的照片。多给它几秒钟，解码这么多数据在任何设备上都要时间。</p>\n<p>JPG 看起来发灰，原因是颜色偏移。Display P3 的颜色会转成标准颜色，在任何修图应用里稍微提高饱和度就能恢复观感。</p>\n<p>实况照片丢了动效，这是正常的。转换器把静态帧导出成 JPG，视频部分按设计会被丢弃。</p>\n<h2 id=\"stop-heic-future\">让以后的照片不再是 HEIC</h2>\n<p>在 iPhone 上打开“设置”，再点“相机”，再点“格式”。选“最兼容”，以后的照片就会存成 JPG，而不是 HEIC。</p>\n<p>代价是存储空间。JPG 照片大约占 HEIC 两倍的地方，相机胶卷会更快装满。</p>\n<p>大多数人还是留着 HEIC、需要时再转更好。省下的空间是实实在在的，转换也只要几秒钟。</p>\n<p>每天都和 Windows 用户分享照片时，换成 JPG 能省掉所有人的转换步骤。按最常收到你照片的人来决定。</p>\n<h2 id=\"photos-in-messages\">转换聊天里收到的照片</h2>\n<p>照片常常以 HEIC 文件的形式来到聊天应用里，在电脑上打不开。朋友从 iPhone 发来照片，你的 Windows 笔记本只显示一个破损图标。</p>\n<p>先把照片保存到设备上，再拖进转换器。直接从聊天应用里转通常行不通，因为文件必须先存在设备上。</p>\n<p>保存后检查照片画质。聊天应用常常会自动压缩图片，保存下来的文件可能已经比原照片画质低了。</p>\n<p>转换后把 JPG 分享回聊天里，其他人需要时也能用。JPG 群里每个人都能打开，原 HEIC 一半人打不开。</p>\n<p>原消息留着当备份。转换出问题时，可以重新下载照片、换不同设置再试，不用请发件人重发。</p>\n<h2 id=\"heic-on-windows\">在 Windows 上转换 HEIC 文件</h2>\n<p>Windows 默认解不了 HEIC，浏览器转换器成了最简单的办法。在 Chrome 或 Edge 里打开工具，解码在标签页里运行。</p>\n<p>不用去 Microsoft Store 安装 HEIF 解码器。转换器自带解码器，Windows 本身永远不需要理解 HEIC。</p>\n<p>从文件资源管理器把 HEIC 文件拖到上传区域。一次可以选很多文件，一批一次点击就能转换。</p>\n<p>转换后，JPG 马上就能在 Windows 照片里打开。也能附到邮件、上传到表格、打印，不用再做任何步骤。</p>\n<p>文件很多时，每批五十张转换。浏览器每批都处理顺畅，一批失败也不会影响其他批次。</p>\n<h2 id=\"heic-for-job-application\">求职申请用的 HEIC 照片转换</h2>\n<p>求职网站列出的接受格式是 JPG 和 PNG，HEIC 照片直接被退回。上传前先转换，并先看清网站规则。</p>\n<p>照片转成 90% 画质的 JPG。人脸保持锐利，颜色保持自然，在招聘者眼里很专业。</p>\n<p>转换后检查文件大小限制。上传上限 2MB 的网站可能拒收 4MB 的 JPG，需要用 100KB 或 200KB 工具压缩。</p>\n<p>尺寸也要检查。要求特定像素尺寸的网站，格式对了、形状不对也会拒收照片。</p>\n<p>提前上传转换好的照片，别拖到截止时间。最后一刻转换没时间修问题，提前上传还有重试的余地。</p>\n<h2 id=\"keeping-converted-copies-organised\">整理好转换后的副本</h2>\n<p>转换后的 JPG 值得起清楚的名字。一个月后，一堆 IMG_4821.jpg 根本没法找。保留原名、换掉后缀，文件一直认得出来。</p>\n<p>转换副本按用途放进文件夹，比如 job-application 或 family-share。按用途命名的文件夹，需要文件时很好找。</p>\n<p>HEIC 原文件放进单独的存档文件夹。它们是画质最好的副本，清楚的分隔能防止两套文件混在一起。</p>\n<p>失败或重复的转换结果及时删掉。半成品堆满的文件夹，每次搜索都慢半拍；整洁的文件夹能让下一次任务更快。</p>\n<p>大批量转换之前，先备份原文件。转好的文件永远变不回完美的原稿，所以原稿值得留一份安全副本。</p>\n<h2 id=\"heic-for-social-media\">社交媒体用的 HEIC 照片转换</h2>\n<p>社交平台接受 HEIC 上传，但上传后还是会转成 JPG 或 WebP。直接上传 JPG，你能自己控制画质，而不是相信平台的转换。</p>\n<p>上传前把照片转成 90% 画质的 JPG。人脸保持锐利，颜色保持自然，平台压缩也有个好的起点。</p>\n<p>转换前先看平台偏好的尺寸。Instagram、Facebook、X 各有理想尺寸，尺寸合适比格式更重要。</p>\n<p>头像用方形裁剪效果最好。转换前先把照片裁成方形，免得平台在尴尬的位置替你裁。</p>\n<p>上传后下载平台上的版本检查一下。快速看一眼已发布的帖子，确认照片在平台处理后依然完好。</p>\n<p>整个流程就是这样：上传、转换、下载。想了解背景，请读<a href=\"/zh/blog/heic-zhuan-jpg-wanquan-zhinan/\">HEIC 转 JPG 完全指南</a>；格式对比请看<a href=\"/zh/blog/heic-vs-jpg/\">HEIC 和 JPG 有什么区别</a>。一次要转换很多种格式时，<a href=\"/zh/zhuanhuan-tupian/\">图片格式转换工具</a>能处理混合批量。</p>\n";

export const FAQS: BlogArticleFaq[] = [{"question":"iPhone 上不用电脑，怎么把 HEIC 转成 JPG？","answer":"在 iPhone 的 Safari 里打开转换器，点上传区域，从图库里选照片。转换在手机上运行，JPG 会下载到“文件”应用里。不用电脑，不用装应用，不用注册账号。"},{"question":"Windows 上能批量把 HEIC 转成 JPG 吗？","answer":"可以。在 Windows 的 Chrome 或 Edge 里打开工具，拖入任意数量的 HEIC 文件，整批打成一个 ZIP 下载。解码在浏览器里运行，Windows 永远不需要自己的 HEIC 支持。"},{"question":"为什么转好的 JPG 比 HEIC 大这么多？","answer":"HEIC 是比 JPG 更高效的格式，同一张照片存成 JPG 需要更多字节。照片本身没变，只是存储效率低了。更大的体积是换来处处能打开的格式的代价。"},{"question":"实况照片转成 JPG 后会怎么样？","answer":"转换器把静态关键照片导出成 JPG，丢掉那段短视频。这对表格、网站和打印是正确的，因为它们需要静态图。想保留动效时，留着原 HEIC，或从“照片”应用里分享实况照片，视频才能留下来。"},{"question":"HEIC 转 JPG 会丢掉照片的拍摄日期吗？","answer":"会的。转好的 JPG 会丢掉 EXIF 元数据，包括原拍摄日期，因为画到画布上会清除这些信息。日期重要时，转换前先记下来，或者下载后在 JPG 文件名里加上日期。"},{"question":"转换失败的 HEIC 文件还有办法吗？","answer":"先在 iPhone 上打开它，确认它是不是真正的 HEIC 文件。能在 iPhone 上打开，就试着单独转换一张，而不是放在批量里。到处都失败的话，文件很可能损坏了，需要从 iPhone 上重新取原照片。"}];
